task.solution:
def merge_config(base, *overrides, strict=False):
    out = dict(base)
    for layer in overrides:
        if strict:
            unknown = set(layer) - set(base)
            if unknown:
                raise KeyError(f"unknown keys: {sorted(unknown)}")
        out.update(layer)
    return out

