from dataclasses import dataclass

@dataclass
class Entry:
    model: str
    tokens: int
    cost: float

class Ledger:
    def __init__(self):
        self._entries = []

    def add(self, model, tokens, cost):
        self._entries.append(Entry(model, tokens, cost))

    @property
    def total(self):
        return sum(e.cost for e in self._entries)

    def by_model(self):
        out = {}
        for e in self._entries:
            out[e.model] = out.get(e.model, 0.0) + e.cost
        return out

    def __len__(self):
        return len(self._entries)

