def load_rows(raws):
    ok, errors = [], []
    for i, raw in enumerate(raws):
        parts = raw.split(",")
        if len(parts) != 2:
            errors.append({"line": i, "raw": raw, "reason": "field count"})
            continue
        rid = parts[0].strip()
        if not rid:
            errors.append({"line": i, "raw": raw, "reason": "empty id"})
            continue
        try:
            score = float(parts[1].strip())
        except ValueError:
            errors.append({"line": i, "raw": raw, "reason": "bad score"})
            continue
        ok.append({"id": rid, "score": score})
    return ok, errors

import json

def read_jsonl(text, required):
    records, errors = [], []
    for lineno, line in enumerate(text.splitlines(), 1):
        if not line.strip():
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            errors.append({"line": lineno, "reason": "invalid json"})
            continue
        missing = sorted(f for f in required if f not in obj)
        if missing:
            errors.append({"line": lineno, "reason": "missing: " + ",".join(missing)})
            continue
        records.append(obj)
    return records, errors

