def windows(xs, size, step):
    if size < 1 or step < 1:
        raise ValueError("size and step must be >= 1")
    for i in range(0, len(xs) - size + 1, step):
        yield list(xs[i:i + size])

import asyncio

async def run_all(items, worker, limit):
    sem = asyncio.Semaphore(limit)

    async def one(x):
        async with sem:
            try:
                value = await worker(x)
            except Exception as e:
                return {"item": x, "ok": False, "error": f"{type(e).__name__}: {e}"}
            return {"item": x, "ok": True, "value": value}

    return list(await asyncio.gather(*[one(x) for x in items]))
